package com.opensocket.aievent.core.resourceaccess.persistence;
import com.opensocket.aievent.core.resourceaccess.contract.*;import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;import java.sql.Timestamp;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;
@DatabaseRepositoryAdapter @ConditionalOnProperty(prefix="resource-access",name={"enabled","attachment-enabled"},havingValue="true")
public final class JdbcAttachmentAccessAuditAdapter implements AttachmentAccessAuditPort {private final JdbcTemplate jdbc;public JdbcAttachmentAccessAuditAdapter(JdbcTemplate j){jdbc=Objects.requireNonNull(j);}@Override public void append(AttachmentDownloadGrant g,String principal,String purpose,String correlation){jdbc.update("insert into resource_attachment_download_audits(tenant_id,audit_id,resource_type,resource_id,principal_id,read_decision_id,download_decision_id,runtime_lease_id,fencing_version,content_handle_id,content_type,size_bytes,sha256,purpose,correlation_id,created_at) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",g.attachmentRef().tenantId(),"ada-"+UUID.randomUUID(),g.attachmentRef().resourceType().name(),g.attachmentRef().resourceId(),principal,g.readDecisionId(),g.downloadDecisionId(),g.runtimeLeaseId(),g.fencingVersion(),g.contentHandle().handleId(),g.contentType(),g.sizeBytes(),g.sha256(),purpose,correlation,Timestamp.from(g.issuedAt()));}}
